import { test, expect } from '@playwright/test';

test.describe('Multi-step form progress indicator', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com/multi-step-form');
  });

  test('should display progress indicator on the first step', async ({ page }) => {
    const progressIndicator = page.getByRole('progressbar');
    await expect(progressIndicator).toBeVisible();
    await expect(progressIndicator).toHaveText('Step 1 of 3');
  });

  test('should update progress indicator on moving to the next step', async ({ page }) => {
    await page.getByRole('button', { name: 'Next' }).click();
    const progressIndicator = page.getByRole('progressbar');
    await expect(progressIndicator).toBeVisible();
    await expect(progressIndicator).toHaveText('Step 2 of 3');
  });
});
